create table if not exists public.quotation(quote_id bigint generated always as identity primary key,quote_number text not null unique,transaction_id bigint references public."transaction"(transaction_id) on delete set null,customer_id bigint not null references public.customers(customer_id),subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),total_amount numeric(24,6) not null default 0 check(total_amount>=0));
create table if not exists public.sales_order(so_id bigint generated always as identity primary key,so_number text not null unique,transaction_id bigint references public."transaction"(transaction_id) on delete set null,customer_id bigint not null references public.customers(customer_id),subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),currency_id bigint not null references public.currencies(currency_id),status_id bigint not null references public.status(status_id));
create table if not exists public.delivery(delivery_id bigint generated always as identity primary key,delivery_number text not null unique,transaction_id bigint references public."transaction"(transaction_id) on delete set null,so_id bigint not null references public.sales_order(so_id),location_id bigint not null references public.locations(location_id),delivery_date date not null);
create table if not exists public.invoice(invoice_id bigint generated always as identity primary key,invoice_number text not null,transaction_id bigint references public."transaction"(transaction_id) on delete set null,customer_id bigint not null references public.customers(customer_id),so_id bigint references public.sales_order(so_id),subsidiary_id bigint not null references public.subsidiaries(subsidiary_id),due_date date not null,total_amount numeric(24,6) not null check(total_amount>=0),unique(invoice_number,customer_id));
create table if not exists public.customer_payment(payment_id bigint generated always as identity primary key,payment_number text not null unique,transaction_id bigint references public."transaction"(transaction_id) on delete set null,customer_id bigint not null references public.customers(customer_id),bank_account_id bigint not null references public.bank_account(bank_account_id),payment_date date not null,amount_received numeric(24,6) not null check(amount_received>0));
create table if not exists public.credit_note(cn_id bigint generated always as identity primary key,cn_number text not null unique,transaction_id bigint references public."transaction"(transaction_id) on delete set null,customer_id bigint not null references public.customers(customer_id),invoice_id bigint not null references public.invoice(invoice_id),amount numeric(24,6) not null check(amount>0));
create table if not exists public.debit_note(dn_id bigint generated always as identity primary key,dn_number text not null unique,transaction_id bigint references public."transaction"(transaction_id) on delete set null,customer_id bigint not null references public.customers(customer_id),invoice_id bigint not null references public.invoice(invoice_id),amount numeric(24,6) not null check(amount>0));
do $$declare t text;begin foreach t in array array['quotation','sales_order','delivery','invoice','customer_payment','credit_note','debit_note']loop execute format('alter table public.%I enable row level security',t);execute format('drop policy if exists "sales_select" on public.%I',t);execute format('drop policy if exists "sales_insert" on public.%I',t);execute format('drop policy if exists "sales_update" on public.%I',t);execute format('drop policy if exists "sales_delete" on public.%I',t);execute format('create policy "sales_select" on public.%I for select to authenticated using(true)',t);execute format('create policy "sales_insert" on public.%I for insert to authenticated with check(true)',t);execute format('create policy "sales_update" on public.%I for update to authenticated using(true) with check(true)',t);execute format('create policy "sales_delete" on public.%I for delete to authenticated using(true)',t);end loop;end$$;
